def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        safe = DAILY_SALARY * 0.28
        if hp <= 2 or no_water_days >= 1:
            safe = DAILY_SALARY * 0.55
        return float(min(budget, safe))

    prev_bids = []
    urgent_count = 0
    rich_urgent_count = 0
    max_opp_budget = 0.0

    for opp in alive:
        obudget = opp.get('budget', 0.0)
        if obudget > max_opp_budget:
            max_opp_budget = obudget

        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev.get('bid', 0.0)))

        ohp = opp.get('hp', 10)
        onwd = opp.get('no_water_days', 0)
        if ohp <= 3 or onwd >= 1:
            urgent_count += 1
            if obudget >= DAILY_SALARY * 0.9:
                rich_urgent_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    contested = len(alive) + 1
    capacity = int(supply // WATER_REQ)
    scarcity = capacity < contested

    base = DAILY_SALARY * 0.42

    if not scarcity:
        base = DAILY_SALARY * 0.34
        if highest_prev > 0:
            base = min(base, max(DAILY_SALARY * 0.26, avg_prev * 0.72))
    else:
        if capacity <= 1:
            base = max(DAILY_SALARY * 0.88, highest_prev + 2.5)
        else:
            base = max(DAILY_SALARY * 0.68, avg_prev + 2.0, highest_prev * 0.9)

    if urgent_count >= 2:
        base += 6.0
    elif rich_urgent_count >= 1:
        base += 4.0

    if hp <= 2:
        base = max(base, highest_prev + 3.0, DAILY_SALARY * 0.96)
    elif hp <= 4 or no_water_days >= 1:
        base = max(base, highest_prev * 0.98, DAILY_SALARY * 0.78)
    elif hp >= 8 and no_water_days == 0 and scarcity and highest_prev >= DAILY_SALARY * 1.4:
        base = min(base, DAILY_SALARY * 0.38)

    if budget < DAILY_SALARY * 0.9:
        base = min(base, budget)
    elif budget > max_opp_budget * 1.2 and hp <= 4:
        base += 4.0

    if day >= 8:
        if hp <= 5:
            base = max(base, DAILY_SALARY * 0.86)
        else:
            base = max(base, DAILY_SALARY * 0.58)

    bid = min(budget, max(0.0, base))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
