def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    total_water_needed = WATER_REQ
    for opp in alive_opponents:
        total_water_needed += opp['water_requirement']

    if my_hp <= 2:
        bid = DAILY_SALARY * 1.25
    elif my_hp == 3:
        bid = DAILY_SALARY * 1.1
    elif my_hp <= 5:
        bid = DAILY_SALARY * 0.9
    else:
        bid = DAILY_SALARY * 0.7

    if current_supply < total_water_needed / 2:
        bid *= 1.15
    elif current_supply < total_water_needed:
        bid *= 1.05
    else:
        bid *= 0.9

    highest_prev_bid = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            highest_prev_bid = max(highest_prev_bid, prev['bid'])

            if opp['agent_id'] == 'Cindy':
                if prev['bid'] > DAILY_SALARY * 0.9 and opp['hp'] <= 5:
                    bid = max(bid, prev['bid'] * 1.05)
                elif prev['bid'] > DAILY_SALARY * 0.7 and opp['hp'] > 5:
                    bid = max(bid, prev['bid'] * 1.02)
            elif opp['agent_id'] == 'Alex':
                if prev['bid'] > DAILY_SALARY * 0.85 and opp['hp'] <= 4:
                    bid = max(bid, prev['bid'] * 1.04)
                elif prev['bid'] > DAILY_SALARY * 0.6 and opp['hp'] > 4:
                    bid = max(bid, prev['bid'] * 1.01)

    if highest_prev_bid > DAILY_SALARY * 0.9:
        bid = max(bid, highest_prev_bid + 5)
    elif highest_prev_bid > DAILY_SALARY * 0.7:
        bid = max(bid, highest_prev_bid + 2)

    remaining_days = EPISODE_DAYS - current_day + 1
    if remaining_days <= 3 and my_budget > DAILY_SALARY * 1.5 * remaining_days:
        bid *= 1.1
    elif my_budget < DAILY_SALARY * 0.8 * remaining_days:
        bid *= 0.9

    bid = min(bid, my_budget)
    bid = max(bid, DAILY_SALARY * 0.15)

    return round(bid, 2)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Alive opponents and yesterday bid extraction
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # If no info, use a conservative bid
    if not alive_opps:
        # If we're in danger, bid more; otherwise keep moderate
        if my_status.get('hp', 0) <= 2 or my_status.get('no_water_days', 0) >= 2:
            return min(my_status.get('budget', 0), DAILY_SALARY * 0.85)
        return min(my_status.get('budget', 0), DAILY_SALARY * 0.55)

    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate competitive pressure from yesterday
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = 0.0
    if len(yesterday_bids) >= 2:
        sorted_b = sorted(yesterday_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    my_hp = int(my_status.get('hp', 0))
    my_no_water_days = int(my_status.get('no_water_days', 0))
    my_budget = float(my_status.get('budget', 0))

    # Convert supply to a coarse expected water count for the day
    # (Used only to scale aggressiveness; actual allocation is determined by bids.)
    # Ensure indices are safe by using int() where needed.
    expected_units = int(supply / WATER_REQ)  # e.g., 15/8->1, 25/8->3
    expected_units = max(1, min(expected_units, 3))

    # Base bid level: aim to beat the likely clearing price when others were aggressive.
    # If highest_prev_bid is high, we must spend more to avoid losing.
    if highest_prev_bid >= DAILY_SALARY * 0.80:
        base = max(highest_prev_bid * 1.02, second_prev_bid * 1.08 + 2.0)
    else:
        # If others weren't too high, bid enough to secure water but not to overspend.
        base = max(DAILY_SALARY * 0.48, highest_prev_bid * 0.92 + 3.0)

    # Urgency adjustments
    if my_hp <= 2:
        base *= 1.25
    elif my_hp <= 4:
        base *= 1.10

    if my_no_water_days >= 2:
        base *= 1.30
    elif my_no_water_days == 1:
        base *= 1.10

    # Supply scaling: when supply is scarce, competition is higher; bid slightly more.
    if supply <= 17.0:
        base *= 1.15
    elif supply >= 22.0:
        base *= 0.95

    # Clamp to budget and reasonable fraction of daily salary
    # Keep some budget for later days.
    max_reasonable = DAILY_SALARY * (0.95 if my_hp <= 2 or my_no_water_days >= 2 else 0.75)
    bid = min(my_budget, max_reasonable, base)

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    # If we are extremely safe, reduce bid to conserve budget
    if my_hp >= 7 and my_no_water_days == 0:
        bid = min(bid, DAILY_SALARY * 0.45)

    return float(bid)
